"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["4240"],{3590(e,n,t){t.r(n),t.d(n,{metadata:()=>a,default:()=>c,frontMatter:()=>o,contentTitle:()=>r,toc:()=>l,assets:()=>d});var a=JSON.parse('{"id":"reference/hardware/protocols/mqtt-av","title":"Using MQTT with AirVantage","description":"av \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/reference/hardware/protocols/mqtt-av.md","sourceDirName":"reference/hardware/protocols","slug":"/reference/hardware/protocols/mqtt-av","permalink":"/personal-av-docs/docs/reference/hardware/protocols/mqtt-av","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/reference/hardware/protocols/mqtt-av.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"Using MQTT with AirVantage","sidebar_label":"Using MQTT with AirVantage","sidebar_position":99,"edition":"av","source":"https://doc.airvantage.net/av/reference/hardware/protocols/mqtt-av","format":"md"}}'),s=t(4848),i=t(8453);let o={title:"Using MQTT with AirVantage",sidebar_label:"Using MQTT with AirVantage",sidebar_position:99,edition:"av",source:"https://doc.airvantage.net/av/reference/hardware/protocols/mqtt-av",format:"md"},r,d={},l=[];function m(e){let n={a:"a",code:"code",p:"p",pre:"pre",strong:"strong",...(0,i.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsxs)(n.p,{children:[":::note Edition\n",(0,s.jsx)(n.strong,{children:"av"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,s.jsx)(n.a,{href:"https://doc.airvantage.net/av/reference/hardware/protocols/mqtt-av",children:"Original page"}),".\n:::"]}),"\n",(0,s.jsx)(n.p,{children:'Using MQTT with AirVantage\nInitializing Table Of Contents...\nThis page explains how to use the MQTT protocol with AirVantage: how to send values and timeseries data, and how to debug communications.\nIntroduction\nThis section explains the payload format you need to use with the MQTT protocol to connect your embedded application to AirVantage Reserved topics.\n(The currently supported version of MQTT is 3.1.1).\nSupported features\nThe following MQTT 3.1 features are supported on the AV Reserved topics:\nPublish / Subscribe\nQoS 0, 1 (at least one-time delivery)\nLast Will & Testament: publish a message when a client disconnects\nProtocol Configuration\nPort:\n1883 or 8883 (SSL/TLS)\nurl:\ntcp://eu.airvantage.net\nUsername:\nSerial Number (but IMEI can be used as well)\nPassword:\nany UTF-8 character. The length is limited to 255 characters.\nClientId:\nThe ClientId must be unique. Use Serial Number\nTopics\nPush data to AirVantage:\n{IMEI or SN}/messages/json\nReceive AirVantage operation tasks:\n{IMEI or SN}/tasks/json\nAcknowledge the commands received on the device:\n{IMEI or SN}/acks/json\nCBOR-encoded messages:\n{IMEI or SN}/messages/ts\n(for Time Series).\nCBOR+zlib messages:\n{IMEI or SN}/messages/tsz\nPublish data\nMQTT is payload-agnostic, so you can use any format as payload.\nBut if you want to interface with the AirVantage data store and tasks topics, you need to respect the specified formats.\nSupported Data type\nThe supported data type are the following JSON data type: double, int, string, boolean, binary and date link.\nName\nComment\nint\ninteger signed 32bits\ndouble\nfloating-point number encoded on 64bits following IEE754 standard\nstring\nUTF-8 text\ndate\ndate must be the number of milliseconds elapsed since 1 January 1970 GMT\nboolean\ntrue/false (0 and 1 are not supported)\nbinary\nBase-64 encoded. Can not be used for a command parameter\nJson Format 1\n{ <timestamp>: { "<dataname>": <value>, "<dataname>": <value>}, ... }\ntimestamp\n: nb of millisecond since 01/01/1970. Optional.\ndataname\n: full path starting with the asset-id\nvalue\n: string value must be quoted, boolean value must be true or false.\nExample\n:\n<asset default-label="My Machine" id="machine">\n<variable default-label="Temperature" path="temperature" type="double"/>\n<variable default-label="Humidity" path="humidity" type="double"/>'}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:' &lt;setting default-label="Threshold" path="threshold" type="int"/&gt;\n'})}),"\n",(0,s.jsx)(n.p,{children:'</asset>\n{ "1349907137000": { "machine.temperature": 23.2, "machine.humidity": 70 },\n"1349908137000": { "machine.temperature": 24.5 },\n"1349909137000": { "machine.temperature": 22.9 },\n"1349907137000": { "machine.threshold": 30}\n}\nAs the timestamp value is optional, the format can be:\n{ "machine.temperature": 23.2, "machine.humidity": 70 }\nWhen the server receives the values, it adds a timestamp.\nJson Format 2\n[{ "<dataname>": [{ "timestamp": <timestamp>, "value:" <value>}, ...], "<dataname>": ... }]\ntimestamp\n: nb of milliseconds since 01/01/1970 (string format)\ndataname\n: full path starting with the asset-id\nvalue\n: string value must be quoted, boolean value must be true or false.\nExample\n:\n[{\n"machine.temperature": [{\n"timestamp" : 1416324560869,\n"value" : 42.2\n},\n{\n"timestamp" : 1416324560869,\n"value" : 24.5\n},\n{\n"timestamp" : 1416324560869,\n"value" : 42.9\n}]\n},\n{\n"machine.threshold": [{\n"timestamp" : 1416324560869,\n"value" : 30\n}]\n}]\nMQTT Time Series Format\nIntroduction\nThis section explains the AirVantage Time Series format for MQTT. This is a compressed format dedicated to sending time-series such as large sensor collections or GPS traces.\nThis format is based on CBOR, an IETF standard\nRFC 7049\nfor Concise Binary Object Representation.\nYou can optionally add an additional layer of\nzlib\ncompression.\nTo receive task messages from AirVantage (read, write, commands) you need to use the JSON topic.\nMQTT Topics\nThe CBOR-encoded messages will be published on the following MQTT topic: {IMEI or SN}/messages/ts (for Time Series).\nFor CBOR+zlib messages: {IMEI or SN}/messages/tsz\nRepresentation\nThis format will let you send a list of data for different timestamps.\nFor example we want to send a car accelerometer X,Y,Z values together with the GPS coordinates (latitude and longitude) and the car speed.\nExample:\nTimestamp (ms)\nX\nY\nZ\nLatitude\nLongitude\nSpeed\n1412320402000\n0\n2\n0\n49.455177\n0.537743\n100\n1412320402100\n0\n3\n0\n49.455177\n0.537743\n98.4\nEncoding\nFor basic compression we can use\ndelta encoding\n, in order to send a smaller number. In place of sending the actual values for each new line, we will just send the delta compared to the previous line. If we look at our previous example, for the second timestamp, rather than sending 1412320402100, we will send the delta: 100.\nTo reduce the size of floating numbers with a fixed precision (like GPS coordinates), we can apply a factor to the samples. In place of encoding the actual floating value we will encode the integer delta.\nTo reduce the size of the timestamp, we will remove the last two zeros because we know we are always sampling every 100ms.\nCBOR is based on the successful JSON data model: numbers, strings, arrays and maps.\nWe can represent CBOR object using JSON, but at the end it will be binary encoded on the wire.\nThe payload for the message is a CBOR map with three entries:\n\u201Ch\u201D the list of data path, in our case [\u201CX\u201D,\u201CY\u201D,\u201CZ\u201D,\u201CLatitude\u201D,\u201CLongitude\u201D,\u201CSpeed\u201D] the first column is always timestamps so we don\u2019t need to specify it in this list\n\u201Cf\u201D the list of factors to apply, in our case [0.01,1,1,1,1000000,1000000,1] the first value is the factor to apply to timestamps\n\u201Cs\u201D the list of samples, we will place the delta encoded values here, in a big list\nAs a JSON representation:\n{\n"h" : [             "x", "y", "z", "lat",    "long",   , "speed" ],'}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:'  "f" : [ 0.01,        1,   1 ,  1,   1000000,  1000000,   1       ],\n\n  "s" : [ 14123204020, 0,   2,   0,   49455177, 537743,    100,\n          1,           0,   1,   0,   0,        0,         -1.6    ]\n'})}),"\n",(0,s.jsx)(n.p,{children:'}\nAs a binary CBOR encoded buffer:\na361688661786179617a636c6174646c6f6e67657370656564616687fb3f847a\ne147ae147b0101011a000f42401a000f42400161738e1b0000000349cefdb400\n02001a02f2a0491a0008348f1864010001000000fbbff999999999999a\nYou can easily verify your CBOR-encoded message using\ncbor.me\nExtra compression\nIf your embedded target allows, you can add another optional layer of compression using zlib according to the\nRFC1950\nstandard. You can use the popular\nzlib\ncompression library.\nHelpful links\ncbor.io\n: for an introduction to CBOR and also a list of implementation in various languages (C, Java, Python, Go, ..)\ncn-cbor\nA constrained node implementation of CBOR in C\nzlib.net\n: the homepage of one of the most popular zlib implementations in C\nminiz\nSingle C file implementations of zlib\nReceive Tasks\nRead or Write Tasks\n[\n{\n"uid" : "<uid>",\n"timestamp" : <timestamp>,\n"read" : [ "<dataname>", ... ]\nOR\n"write" : [ { "<dataname>" : <value> }, ... ]\n}\n]\nuid:\njob universal identifier\ntimestamp:\nnb of milliseconds since 01/01/1970 (string format)\ndataname:\nfull path with asset-id to identify the setting\nvalue:\nthe new value of the setting. See section \u201CSupported data types\u201D.\nYou can send either a \u201Cread\u201D or a \u201Cwrite\u201D task, but not both at the same time.\nA single task can be sent at a given time.\nExample\n:\n[\n{\n"uid" : "3c12547b613740adb686271bdc8f097c",\n"timestamp" : 1348836320188,\n"read" : ["machine.temperature"]\n}\n]\nor\n[\n{\n"uid": "8006cc58ba2141f69161a78f1bfdea1d",\n"timestamp": 1348836320566,\n"write" : [{"machine.threshold" : 25}]\n}\n]\nCustomer command Tasks\n[\n{\n"uid" : "<uid>",\n"timestamp" : <timestamp>,\n"command" : {"id": "<command-id",\n"params": {"<param-name>":"<param-value", ...}\n}\n}\n]\nuid\n:job universal identifier\ntimestamp\n: nb of milliseconds since 01/01/1970 (string format)\ncommand-id\n: full path with asset-id to identify the command.\nparam-name\n: name of the parameter.\nparam-value\n: value of the parameter\nA single command can be sent at a given time.\nExample\n:\n<asset default-label="My Machine" id="machine">\n<command path="sendMessage" default-label="send Message">\n<parameter id="message" default-label="Message" type="string" />\n</command>\n</asset>\n[\n{\n"uid" : "e87b35c3c2e2417b902277ff9d049d70",\n"timestamp" : 1416324560869,\n"command" : {"id": "machine.sendMessage",\n"params": {"message":"Hello World!"}\n}\n},\n...\n]\nAcknowledging tasks\nOnce you process a task from AirVantage you should acknowledge it. You can provide a success or error acknowledgement (with an optional error message).\n[\n{\n"uid" : "<uid of the acknownleged task>",\n"status" : "<OK or ERROR>",\n"message" : "Failure details"\n},\n...\n]\nA failure message is only needed when the status is ERROR.\nA timestamp is optional.\nExample\n:\n[\n{"uid": "8006cc58ba2141f69161a78f1bfdea1d", "status" : "OK"},\n{"uid": "3c12547b613740adb686271bdc8f097c", "status" : "KO", "message" : "Crashed in flames! Error code: 12345"}\n]\nTroubleshooting communications\nThis section explains how to receive trace logs of the data you are sending by subscribing to the MQTT Errors topic.\nWhen using the MQTT protocol to connect an embedded application to AirVantage, developers can subscribe to the\nerrors\nMQTT topic, to get notified when a message contains an invalid payload.\nUse a different clientId to connect to AirVantage using your device\u2019s username (serial number or IMEI) and password.\nMonitor JSON errors\nSuppose you publish a message on topic\n{IMEI or SN}/messages/json\nwith an invalid JSON format:\n// Invalid JSON - timestamp should be a string\n{ 12346013564 : { "temperature" : 42 } }\nThe JSON payload is invalid because the timestamp is expected to be a JSON string (formats explained above).\nYou can subscribe to\nerrors\nto receive a message, with a payload containing 3 lines in text format (separated by\n\\n\n):\nthe topic on which the initial message was published\nthe payload of the message\na diagnostic message describing the error\nWith the previous request, you would receive:\n{IMEI or SN}/messages/json\n{ 12346013564 : { "temperature" : 42 } }\ninvalid character \'1\' looking for beginning of object key string\nMonitor CBOR errors\nSuppose you publish on\n{IMEI or SN}/messages/ts\nthe CBOR corresponding to the following JSON message:\n// Invalid CBOR, a timestamp is missing in the sample\n{\n"h" : [             "x", "y", "z", "lat",    "long",   , "speed" ],'}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:'  "f" : [ 0.01,        1,   1 ,  1,   1000000,  1000000,   1       ],\n\n  "s" : [ 0,   2,   0,   49455177, 537743,    100 ]\n'})}),"\n",(0,s.jsxs)(n.p,{children:["}\nTime Series format is explained earlier on this page.\nYou can subscribe to\nerrors\nto receive a message, with a payload containing 3 lines of text (separated by\n\\n\n):\nthe topic on which the message was published\nthe payload of the message (encoded as UTF-8)\na diagnostic message describing the error\nWith the previous request, you would receive:\n{IMEI or SN}/messages/tz\n[Encoded payload]\nNot enough CBOR samples at line 0 ; found 6, expected 7.\nSee ",(0,s.jsx)(n.a,{href:"https://doc.airvantage.net/av/reference/hardware/protocols/mqtt-ts/",children:"https://doc.airvantage.net/av/reference/hardware/protocols/mqtt-ts/"}),"\nMore on MQTT\nMQTT.org\nEclipse Paho\nMQTT standard at OASIS\nUnderstand the MQTT protocol\nhiveMQ\nGetting started with MQTT\nTutorials and code samples\nUsing MQTT with BeagleBone Black in Javascript, refer to\ntutorial\n.\nUsing MQTT with an raspberry Pi in c, refer to\ntutorial\n.\nUsing MQTT with an HL6 in ruby, refer to\ntutorial\n.\nUsing MQTT with a SL808xT in c, refer to\ntutorial\n.\nUsing MQTT with GX440 in lua, see this\ntutorial\n.\nSimulate a single system communicating with AirVantage via MQTT\ntutorial\nIf you don\u2019t find you device in this list, refer to this\ntutorial\n.\nYou can also learn how to simulate a single system communicating with AirVantage via MQTT via the MQTTLens Chrome application, using this\ntutorial\n."]})]})}function c(e={}){let{wrapper:n}={...(0,i.R)(),...e.components};return n?(0,s.jsx)(n,{...e,children:(0,s.jsx)(m,{...e})}):m(e)}},8453(e,n,t){t.d(n,{R:()=>o,x:()=>r});var a=t(6540);let s={},i=a.createContext(s);function o(e){let n=a.useContext(i);return a.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function r(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:o(e.components),a.createElement(i.Provider,{value:n},e.children)}}}]);